Cases.Template:
{% for i in items %}
{{ i }}
{% endfor %}

{%- macro nest_dict(o, i, ff='') %}
  {{- caller(ff) }}
  {%- for k, v in o|items %}
    {{- i + k + ': ' }}
    {%- if v is mapping %}
      {{- '{' }}
      {% call(f) nest_dict(v, i + '    ') %}
        {{- 'fail' if ff is undefined }}
      {%- endcall %}
      {{- i + '}' }}
    {% else %}
      {{- v|string }}
    {% endif %}
  {%- endfor %}
{%- endmacro %}
{%- call(f) nest_dict({'root1': 1, 'root2': {'nest1': 1, 'nest2': {'nest3': 2}}}, '    ', 'Dict') %}
  {{- 'fail' if ff is defined }}
  {{- f + ' {' }}
{% endcall %}
{{- '}' }}

Cases.Expected:
Dict {
    root1: 1
    root2: {
        nest1: 1
        nest2: {
            nest3: 2
        }
    }
}
